
/*
 * ChatCompletionResponseMessage.h
 *
 * A chat completion message generated by the model.
 */

#ifndef TINY_CPP_CLIENT_ChatCompletionResponseMessage_H_
#define TINY_CPP_CLIENT_ChatCompletionResponseMessage_H_


#include <string>
#include "bourne/json.hpp"
#include "Helpers.h"
#include "ChatCompletionMessageToolCall.h"
#include "ChatCompletionResponseMessage_audio.h"
#include "ChatCompletionResponseMessage_function_call.h"
#include <list>

namespace Tiny {


/*! \brief A chat completion message generated by the model.
 *
 *  \ingroup Models
 *
 */

class ChatCompletionResponseMessage{
public:

    /*! \brief Constructor.
	 */
    ChatCompletionResponseMessage();
    ChatCompletionResponseMessage(std::string jsonString);


    /*! \brief Destructor.
	 */
    virtual ~ChatCompletionResponseMessage();


    /*! \brief Retrieve a bourne JSON representation of this class.
	 */
    bourne::json toJson();


    /*! \brief Fills in members of this class from bourne JSON object representing it.
	 */
    void fromJson(std::string jsonObj);

	/*! \brief Get The contents of the message.
	 */
	std::string getContent();

	/*! \brief Set The contents of the message.
	 */
	void setContent(std::string  content);
	/*! \brief Get The refusal message generated by the model.
	 */
	std::string getRefusal();

	/*! \brief Set The refusal message generated by the model.
	 */
	void setRefusal(std::string  refusal);
	/*! \brief Get The tool calls generated by the model, such as function calls.
	 */
	std::list<ChatCompletionMessageToolCall> getToolCalls();

	/*! \brief Set The tool calls generated by the model, such as function calls.
	 */
	void setToolCalls(std::list <ChatCompletionMessageToolCall> tool_calls);
	/*! \brief Get The role of the author of this message.
	 */
	std::string getRole();

	/*! \brief Set The role of the author of this message.
	 */
	void setRole(std::string  role);
	/*! \brief Get 
	 */
	ChatCompletionResponseMessage_function_call getFunctionCall();

	/*! \brief Set 
	 */
	void setFunctionCall(ChatCompletionResponseMessage_function_call  function_call);
	/*! \brief Get 
	 */
	ChatCompletionResponseMessage_audio getAudio();

	/*! \brief Set 
	 */
	void setAudio(ChatCompletionResponseMessage_audio  audio);


    private:
    std::string content{};
    std::string refusal{};
    std::list<ChatCompletionMessageToolCall> tool_calls;
    std::string role{};
    ChatCompletionResponseMessage_function_call function_call;
    ChatCompletionResponseMessage_audio audio;
};
}

#endif /* TINY_CPP_CLIENT_ChatCompletionResponseMessage_H_ */
